    function run(uint _am, uint _minSum, uint _deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_deposit)); require(_deposit <= 1000000000000000000000000000000);
        require(_minSum <= _deposit);
        require(_am <= _deposit);
        require(address(this).balance >= _deposit);
        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
