pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _am, uint256 _minSum, uint256 _deposit) internal {
        _deposit = bound(_deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_minSum <= _deposit);
        vm.assume(_am <= _deposit);
        vm.assume(address(this).balance >= _deposit);
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: _deposit}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeEth = address(this).balance;
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterEth = address(this).balance;
        assertTrue(reverted || (beforeBal == afterBal + _am && afterEth == beforeEth + _am));
    }

    function testFuzz_run(uint256 _am, uint256 _minSum, uint256 _deposit) public {
        _run(_am, _minSum, _deposit);
    }

    receive() external payable {}
}
